import {seed,today} from './data.js';
import {load,act,total,paid,balance,stock,expectedCash,openOrders,money,refunded} from './model.js';
let state=load(), page=location.hash.slice(1)||'salon',zone='Salón principal',selected=1042,account=0,category='Todos',station='Todas',contactType='customers',showInactive=false,query='',pickedProduct=1;
let lastFocus=null,toastTimer;
const root=document.querySelector('#app'),modalRoot=document.querySelector('#modal-root');
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={
 grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',table:'M4 8h16v8H4zM7 3h10M7 21h10M1 10v4M23 10v4',chef:'M7 14v6h10v-6M7 16h10M7 14C1 14 1 6 7 6c1-5 9-5 10 0 6 0 6 8 0 8',calendar:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16M8 14h2M14 14h2M8 17h2',bike:'M5 20a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM19 20a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM5 16l5-8 5 8h4L15 5h3M8 8h5',wallet:'M3 6h16v14H3zM3 6V4l14-2v4M15 11h7v5h-7zM18 13.5h.1',box:'m3 7 9-5 9 5v10l-9 5-9-5V7Zm0 0 9 5 9-5M12 12v10M7 4.5l10 5',cart:'M2 3h3l3 13h11l3-9H6M9 21h.01M18 21h.01M9 19a1 1 0 1 0 0 2 1 1 0 0 0 0-2ZM18 19a1 1 0 1 0 0 2 1 1 0 0 0 0-2Z',book:'M12 5v16M12 5C9 2 5 2 2 3v16c4-1 7-1 10 2 3-3 6-3 10-2V3c-3-1-7-1-10 2Z',receipt:'M5 2v20l3-2 4 2 4-2 3 2V2l-3 2-4-2-4 2-3-2ZM9 8h6M9 12h6M9 16h4',users:'M16 21v-3c0-5-12-5-12 0v3M10 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM17 4a4 4 0 0 1 0 7M20 21v-3c0-2-1-3-3-4',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4ZM8 12l3 3 5-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 2h6l1 3 3 1 3 5-2 2v3l-3 4h-3l-2 2-3-2H6l-4-4v-3l-1-2 3-5 3-1 2-3Z',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20ZM12 6v6l4 2',plus:'M12 5v14M5 12h14',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',arrow:'M4 12h16m-6-6 6 6-6 6',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Zm5-2 6 6',bell:'M5 17h14l-2-4V8a5 5 0 0 0-10 0v5l-2 4ZM10 21h4',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20ZM9 8c0-4 7-3 6 1-.5 2-3 2-3 5M12 18h.01',store:'M4 10v11h16V10M2 10l3-7h14l3 7M2 10c0 4 5 4 5 0 0 4 5 4 5 0 0 4 5 4 5 0 0 4 5 4 5 0M9 21v-7h6v7',logout:'M9 4H3v16h6M9 12h12m-5-5 5 5-5 5',menu:'M4 6h16M4 12h16M4 18h16',edit:'m15 4 5 5M3 21l5-1L21 7c2-2-2-6-4-4L4 16l-1 5Z',trash:'M3 6h18M6 6l1 15h10l1-15M9 6V3h6v3M10 10v7M14 10v7',restore:'M3 3v6h6M3 9c3-8 17-8 18 2 1 10-14 13-17 4',eye:'M1 12s4-7 11-7 11 7 11 7-4 7-11 7S1 12 1 12ZM12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z',leaf:'M4 20C0 9 10 3 21 3c0 11-6 20-17 17ZM4 20 17 7',drink:'M6 3h12l-1 11c-1 5-9 5-10 0L6 3ZM12 17v5M8 22h8M7 8h10',plate:'M12 20a8 8 0 1 0 0-16 8 8 0 0 0 0 16ZM12 17a5 5 0 1 0 0-10 5 5 0 0 0 0 10ZM1 3v6M1 12v9M23 3v18',cake:'M4 12h16v9H4zM3 12c0-4 4-4 6-1 2-3 4-3 6 0 2-3 6-3 6 1M8 8V5M16 8V5M8 2v.1M16 2v.1',pin:'M12 22s8-8 8-14a8 8 0 0 0-16 0c0 6 8 14 8 14ZM12 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z',send:'m22 2-7 20-4-9L2 9 22 2ZM11 13 22 2',split:'M5 3v6c0 3 14 3 14 6v6M5 21v-6c0-3 14-3 14-6V3m-3 3 3-3 3 3M2 18l3 3 3-3',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20ZM12 11v6M12 7h.01',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7',pause:'M8 5v14M16 5v14',play:'m7 3 14 9-14 9V3Z',phone:'M5 3H2c-1 11 10 22 21 19v-4l-6-3-3 3c-3-2-6-5-7-8l3-2-3-5H5Z'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.box}"/></svg>`;
const btn=(label,action,attrs='',style='',ico='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const ib=(label,action,ico,attrs='',cls='')=>`<button type="button" class="icon-btn ${cls}" data-action="${action}" ${attrs} title="${h(label)}" aria-label="${h(label)}">${icon(ico)}</button>`;
const labels={NUEVO:'Por enviar',PENDIENTE:'Pendiente',REGISTRADO:'Registrado',PREPARACION:'En preparación',LISTO:'Listo para servir',ENTREGADO:'Entregado',CANCELADO:'Cancelado',CANCELADA:'Cancelada',ABIERTA:'Abierta',CERRADA:'Cerrada',CONFIRMADA:'Confirmada',ATENDIDA:'Atendida',NO_ASISTIO:'No asistió',BORRADOR:'Borrador',RECIBIDA:'Recibida',EN_RUTA:'En ruta',SIMULADO:'Simulado',SALON:'Salón',LLEVAR:'Para llevar',DELIVERY:'Delivery'};
const pill=(text,color='')=>`<span class="pill ${color}"><i class="dot"></i>${h(text)}</span>`;
const statePill=v=>pill(labels[v]||v,['LISTO','CONFIRMADA','RECIBIDA','ABIERTA','ATENDIDA'].includes(v)?'green':['PREPARACION','PENDIENTE','BORRADOR','REGISTRADO'].includes(v)?'orange':['CANCELADO','CANCELADA','NO_ASISTIO'].includes(v)?'red':'blue');
const time=d=>new Date(d).toLocaleTimeString('es-PE',{hour:'2-digit',minute:'2-digit',hour12:false});
const date=d=>new Date(d.includes('T')?d:d+'T12:00:00').toLocaleDateString('es-PE',{day:'2-digit',month:'short'});
const mins=o=>Math.max(1,Math.round((Date.now()-new Date(o.createdAt))/60000));
const tableName=o=>o.table?state.tables.find(t=>t.id===o.table)?.name:labels[o.type];
const orderById=id=>state.orders.find(o=>o.id===+id);
const empty=(title,description,ico='box',action='')=>`<div class="empty"><div class="empty-icon">${icon(ico)}</div><h3>${title}</h3><p>${description}</p>${action}</div>`;
const head=(title,desc,actions='',eyebrow='OPERACIÓN DIARIA')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}</div></div>`;
const metric=(label,value,caption,ico,color='')=>`<div class="metric ${color}"><div><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-caption">${caption}</div></div><div class="metric-icon">${icon(ico)}</div></div>`;
const note=(text,color='')=>`<div class="note-box ${color}">${icon('info')}<div>${text}</div></div>`;
const search=(placeholder='Buscar...',id='page-search')=>`<label class="search">${icon('search')}<input type="search" id="${id}" value="${h(query)}" placeholder="${placeholder}" aria-label="${placeholder}"></label>`;
const option=(value,text,selectedValue)=>`<option value="${h(value)}" ${String(value)===String(selectedValue)?'selected':''}>${h(text)}</option>`;
const input=(label,name,value='',type='text',extra='',full=false)=>`<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${h(value)}" ${extra}></label>`;
const select=(label,name,options,full=false)=>`<label class="field ${full?'full':''}">${label}<select name="${name}">${options}</select></label>`;
const textarea=(label,name,value='',required=false)=>`<label class="field full">${label}<textarea name="${name}" ${required?'required':''}>${h(value)}</textarea></label>`;
const formEnd=(text='Guardar',style='primary')=>`<div class="form-error" role="alert"></div><div class="modal-actions">${btn('Cancelar','close-modal')}<button class="btn ${style}" type="submit">${text}${icon('arrow')}</button></div></form>`;
const formStart=(type,data='')=>`<form data-form="${type}" ${data}>`;
function toast(text,error=false){const el=document.querySelector('#toast');el.textContent=text;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',4500);}
function save(){try{localStorage.setItem('mesa-demo-v1',JSON.stringify(state));}catch{toast('No se pudo guardar en este navegador. Los cambios durarán esta sesión.',true);}}
function perform(action,data={},message='Cambios guardados',close=true){try{const r=act(state,action,data);state=r.state;save();if(close)closeModal();render();if(message)toast(message);return r;}catch(e){const error=modalRoot.querySelector('.form-error');if(error)error.textContent=e.message;else toast(e.message,true);return null;}}
function modal(title,subtitle,body,wide=false){lastFocus=document.activeElement;modalRoot.innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${h(subtitle)}</p></div>${ib('Cerrar ventana','close-modal','close')}</header><div class="modal-body">${body}</div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>{const focus=modalRoot.querySelector('input:not([type=hidden]),select,textarea,button');focus?.focus();},10);}
function closeModal(){modalRoot.innerHTML='';document.body.style.overflow='';lastFocus?.isConnected&&lastFocus.focus();}
const navGroups=[['OPERACIÓN',[['dashboard','Resumen','grid'],['salon','Salón y pedidos','table'],['cocina','Cocina','chef'],['reservas','Reservas','calendar'],['delivery','Delivery','bike']]],['GESTIÓN',[['caja','Caja y cobros','wallet'],['compras','Compras','cart'],['inventario','Inventario','box'],['carta','Carta y recetas','book'],['comprobantes','Comprobantes','receipt']]],['ADMINISTRACIÓN',[['contactos','Clientes y proveedores','users'],['usuarios','Equipo y accesos','shield'],['auditoria','Auditoría','clock'],['configuracion','Configuración','settings']]]];
function render(){if(!navGroups.flatMap(g=>g[1]).some(n=>n[0]===page))page='salon';const nav=navGroups.flatMap(g=>g[1]).find(n=>n[0]===page);const activeCount=openOrders(state).length;const group=navGroups.find(g=>g[1].some(n=>n[0]===page))[0];root.innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><a href="#salon" class="brand" aria-label="Mesa, inicio"><svg class="brand-mark" viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M5 25V7l11 14L27 7v18M5 15l11 14 11-14" stroke="currentColor" stroke-width="2.4" stroke-linejoin="round"/></svg>mesa<span class="brand-dot">.</span></a><div class="workspace">${icon('store')}<div><strong>${h(state.settings.name)}</strong><small>${h(state.settings.branch)}</small></div></div><nav aria-label="Menú principal">${navGroups.map(([label,items])=>`<p class="nav-label">${label}</p><div class="nav-list">${items.map(([key,name,ico])=>`<a class="nav-link ${page===key?'active':''}" href="#${key}" ${page===key?'aria-current="page"':''}>${icon(ico)}${name}${key==='salon'?`<span class="nav-count">${activeCount}</span>`:''}</a>`).join('')}</div>`).join('')}</nav><div class="sidebar-bottom"><div class="demo-panel"><strong><i class="dot"></i> Tu restaurante, en un solo lugar</strong>Prototipo · datos de ejemplo</div><div class="profile"><div class="avatar">VT</div><div><strong>Valeria Torres</strong><small>Administradora · sesión demo</small></div>${icon('shield')}</div></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb">${ib('Abrir menú','menu','menu','','mobile-menu')}<span>${group.charAt(0)+group.slice(1).toLowerCase()}</span><span>/</span><strong>${nav[1]}</strong></div><div class="top-actions"><span class="top-date">${new Date().toLocaleDateString('es-PE',{weekday:'long',day:'numeric',month:'long'})}</span><span class="session-indicator"><i class="dot"></i>Caja ${state.session.state==='ABIERTA'?'abierta':'cerrada'}</span>${ib('Cómo usar el prototipo','help','help')}${ib('Ver alertas de operación','alerts','bell','','notify-button')}</div></header><main id="main" class="content" tabindex="-1">${views[page]()}<footer class="footer"><span><strong>mesa.</strong> &nbsp; Hecho para tu día a día.</span><span>Datos de ejemplo · guardados en este navegador</span></footer></main></div></div>`;}
function salon(){const occupied=openOrders(state).filter(o=>o.table);const free=state.tables.filter(t=>t.es_activo&&t.habilitada&&!occupied.some(o=>o.table===t.id)).length;const ready=state.orders.flatMap(o=>!o.closedAt?o.lines:[]).filter(l=>l.state==='LISTO').length;const due=openOrders(state).reduce((sum,o)=>sum+balance(state,o),0);let selectedOrder=orderById(selected);if(!selectedOrder||selectedOrder.closedAt)selectedOrder=undefined;return head('El salón, bajo control','Cada mesa, cada pedido. Todo listo para un buen servicio.',btn('Nueva reserva','new-reservation','','','calendar')+btn('Nuevo pedido','new-order','','primary','plus'))+`<div class="metrics">${metric('Mesas ocupadas',`${occupied.length} <small>/ ${state.tables.filter(t=>t.es_activo&&t.habilitada).length}</small>`,'Servicio en curso','table')}${metric('Mesas disponibles',free,'Listas para recibir','users')}${metric('Productos listos',ready,'Pendientes de servir','chef','orange')}${metric('Por cobrar',money(due),openOrders(state).length+' pedidos abiertos','wallet','blue')}</div><div class="floor-layout"><section><div class="floor-toolbar"><div class="tabs" role="group" aria-label="Zona del restaurante">${['Salón principal','Terraza','Para llevar'].map(z=>`<button class="tab ${zone===z?'active':''}" data-action="zone" data-zone="${z}">${z}${z==='Salón principal'?'<small>8</small>':''}</button>`).join('')}</div><div class="legend"><span><i class="dot free"></i>Libre</span><span><i class="dot occupied"></i>Ocupada</span><span><i class="dot ready"></i>Por cobrar</span></div></div>${zone==='Para llevar'?takeaway():`<div class="room"><div class="room-label">${zone==='Terraza'?'AL AIRE LIBRE':'SALÓN PRINCIPAL'} <span>·</span> ${state.tables.filter(t=>t.zone===zone).length} MESAS</div><div class="table-grid">${state.tables.filter(t=>t.zone===zone).map(t=>{const o=occupied.find(o=>o.table===t.id),disabled=!t.habilitada||!t.es_activo;const ready=o?.state==='ENTREGADO';return`<button class="table-card ${o?'occupied':''} ${ready?'ready':''} ${selectedOrder?.table===t.id?'selected':''} ${disabled?'disabled':''}" data-action="table" data-id="${t.id}" aria-label="${t.name}, ${disabled?'no habilitada':o?'ocupada, '+money(total(o)):'disponible'}">${selectedOrder?.table===t.id?`<span class="selected-check">${icon('check')}</span>`:''}<span class="table-capacity">${icon('users')} ${o?o.guests:t.capacity} ${o?'comensales':'personas'}</span><h3>${t.name}</h3><span class="table-status">${disabled?'No habilitada':o?(ready?'Por cobrar':'Ocupada'):'Disponible'}</span>${o?`<span class="table-price">${money(total(o))}</span><span class="table-timer">${mins(o)} min · ${h(o.waiter)}</span>`:`<span class="table-timer">${disabled?'Fuera de servicio':'Abrir pedido'}</span>`}</button>`;}).join('')}</div><div class="room-footer"><span><i></i> ${zone==='Terraza'?'ACCESO A TERRAZA':'INGRESO PRINCIPAL'}</span><span>${icon('leaf')} ${zone==='Terraza'?'TERRAZA':'VENTANAL'}</span></div></div>`}<div class="floor-note">${icon('calendar')}<div><strong>Próximas reservas</strong> &nbsp; ${state.reservations.filter(r=>r.date===today()&&['PENDIENTE','CONFIRMADA'].includes(r.state)).map(r=>`${h(r.start)} · ${h(r.name)} (${r.guests} personas)`).join(' &nbsp; / &nbsp; ')||'No hay reservas pendientes para hoy.'}</div></div></section>${orderPanel(selectedOrder)}</div>`;}
function takeaway(){const orders=openOrders(state).filter(o=>!o.table);return`<div class="panel">${orders.length?orders.map(o=>`<div class="panel-header"><div><h2>#${o.id} · ${h(o.customer)}</h2><p>${labels[o.type]} · ${mins(o)} min · ${money(total(o))}</p></div>${btn('Ver pedido','select-order',`data-id="${o.id}"`,'small','arrow')}</div>`).join(''):empty('Sin pedidos para llevar','Crea un pedido para recoger o enviar.','cart',btn('Nuevo pedido','new-order','','primary','plus'))}</div>`;}
function orderPanel(o){if(!o)return`<aside class="panel order-panel">${empty('Una buena atención comienza aquí','Selecciona una mesa para abrir o consultar su pedido.','table',btn('Abrir un pedido','new-order','','primary','plus'))}</aside>`;const lines=o.lines.filter(l=>l.state!=='CANCELADO'&&(!account||l.account===account));const locked=state.payments.some(p=>p.order===o.id);const hasNew=o.lines.some(l=>l.state==='NUEVO');return`<aside class="panel order-panel"><div class="order-top"><div class="order-title"><h2>${h(tableName(o))}</h2>${statePill(o.state)}</div><div class="order-meta"><span>Pedido #${o.id}</span><span>${icon('users')}${o.guests} personas</span><span>${icon('clock')}${mins(o)} min</span></div></div><div class="order-accountbar"><select aria-label="Cuenta del pedido" id="order-account">${option(0,'Todas las cuentas',account)}${o.accounts.map(a=>option(a,'Cuenta '+a,account)).join('')}</select><button class="text-btn" data-action="split" data-id="${o.id}" ${locked?'disabled':''}>Dividir cuenta</button></div><div class="order-items">${lines.length?lines.map(l=>`<div class="order-item"><div class="qty-box">${l.qty}×</div><div class="order-item-main"><div class="order-item-name">${h(l.name)}</div>${l.note?`<div class="order-item-note">${h(l.note)}</div>`:''}<div class="order-item-bottom">${statePill(l.state)}${o.accounts.length>1?`<span class="subtle">C${l.account}</span>`:''}${l.state==='LISTO'?`<button class="text-btn" data-action="line-state" data-order="${o.id}" data-line="${l.id}" data-state="ENTREGADO">Servir</button>`:''}</div></div><div class="order-item-price">${money(l.qty*l.price)}${!l.sent?ib('Retirar '+l.name,'remove-line','close',`data-order="${o.id}" data-line="${l.id}"`):''}</div></div>`).join(''):empty('Pedido sin consumos','Agrega el primer producto.','plate')}</div>${!locked?`<button class="add-dish" data-action="add-product" data-id="${o.id}">${icon('plus')} Agregar productos</button>`:''}<div class="order-totals"><div class="total-line"><span>Consumo ${account?'· cuenta '+account:''}</span><span>${money(total(o,account))}</span></div><div class="total-line"><span>Pagado</span><span>${money(paid(state,o,account))}</span></div><div class="total-line big"><span>Por cobrar</span><strong>${money(balance(state,o,account))}</strong></div></div><div class="order-actions">${hasNew?btn('Enviar a preparación','send',`data-id="${o.id}"`,'primary full','send'):''}${balance(state,o,account)>0?btn('Cobrar '+money(balance(state,o,account)),'pay',`data-id="${o.id}"`,'accent full','wallet'):total(o)>0?btn('Cerrar y liberar mesa','close-order',`data-id="${o.id}"`,'primary full','check'):''}${!locked?btn('Cancelar pedido','cancel-order',`data-id="${o.id}"`,'ghost small'):''}<div class="order-bottom-note">Precios de demostración · incluyen impuestos</div></div></aside>`;}
function cocina(){const open=openOrders(state);const all=open.flatMap(o=>o.lines.filter(l=>l.sent&&(!['ENTREGADO','CANCELADO'].includes(l.state))&&(station==='Todas'||l.station===station)));return head('La cocina está en marcha','Una comanda clara, un servicio a tiempo.',`<div class="tabs">${['Todas','Cocina','Barra'].map(s=>`<button class="tab ${station===s?'active':''}" data-action="station" data-station="${s}">${s}</button>`).join('')}</div>`)+`<div class="kanban">${['PENDIENTE','PREPARACION','LISTO'].map((st,n)=>`<section class="kanban-col"><div class="kanban-title"><span><i class="dot" style="color:${['#bc976d','#b6804e','#739069'][n]}"></i>${['Por preparar','En preparación','Listo para servir'][n]}</span><small>${all.filter(l=>l.state===st).length}</small></div>${open.filter(o=>o.lines.some(l=>all.includes(l)&&l.state===st)).map(o=>`<article class="ticket"><div class="ticket-top"><div><h3>${h(tableName(o))} <span class="subtle">#${o.id}</span></h3><small>${time(o.createdAt)} · ${h(o.waiter)}</small></div>${pill(mins(o)+' min',mins(o)>25?'orange':'')}</div><div class="ticket-lines">${o.lines.filter(l=>all.includes(l)&&l.state===st).map(l=>`<div class="ticket-line"><div><strong>${l.qty}× &nbsp;${h(l.name)}</strong><span class="pill">${h(l.station)}</span></div>${l.note?`<p>${h(l.note)}</p>`:''}${btn(['Comenzar preparación','Marcar listo','Marcar servido'][n],'line-state',`data-order="${o.id}" data-line="${l.id}" data-state="${['PREPARACION','LISTO','ENTREGADO'][n]}"`,'small '+(n===1?'primary':''),n===1?'check':'arrow')}</div>`).join('')}</div></article>`).join('')||`<div class="empty"><div class="empty-icon">${icon('check')}</div><p>${n===0?'Todo al día.':'Sin productos en esta etapa.'}</p></div>`}</section>`).join('')}</div><div class="gap-top">${note('Al comenzar la preparación se registra una sola vez el consumo de los insumos de la receta. Los productos sin receta no generan consumo automático.')}</div>`;}
function dashboard(){const collected=state.payments.reduce((a,p)=>a+p.amount,0),refunds=state.refunds.reduce((a,r)=>a+r.amount,0),active=openOrders(state),low=state.ingredients.filter(i=>stock(state,i.id)<i.min);const byMethod=['EFECTIVO','YAPE','PLIN','TARJETA','TRANSFERENCIA'].map(m=>({name:m,total:state.payments.filter(p=>p.method===m).reduce((a,p)=>a+p.amount,0)}));const max=Math.max(1,...byMethod.map(v=>v.total));return head('Un buen día comienza con orden','Una vista de lo que está pasando en tu restaurante.',btn('Ir al salón','go',`data-page="salon"`,'primary','arrow'))+`<div class="dashboard-greeting"><div><div class="eyebrow">${h(state.settings.name)}</div><h2>Hola, Valeria. Tu equipo está en marcha.</h2><p>Tienes ${active.length} pedidos en servicio y ${low.length} insumos por reponer.<br>Vamos a hacer que cada mesa cuente.</p></div>${icon('leaf')}</div><div class="metrics">${metric('Cobros netos',money(collected-refunds),'Cobros menos devoluciones','wallet')}${metric('Pedidos en curso',active.length,'Salón, llevar y delivery','table')}${metric('Ticket cobrado',money(Math.round(collected/Math.max(1,new Set(state.payments.map(p=>p.order)).size))),'Promedio por pedido con pagos','receipt','blue')}${metric('Alertas de stock',low.length,'Por debajo del mínimo','box','orange')}</div><div class="two-col"><div class="stack"><section class="panel"><div class="panel-header"><div><h2>Cobros por método de pago</h2><p>Operaciones de esta demostración</p></div>${pill(money(collected),'green')}</div><div class="panel-body"><div class="chart">${byMethod.map(v=>`<div class="chart-col"><span>${money(v.total)}</span><div class="chart-bar" style="height:${Math.max(2,v.total/max*115)}px"></div><span>${v.name}</span></div>`).join('')}</div></div></section><section class="panel"><div class="panel-header"><h2>Atención en curso</h2>${btn('Ver pedidos','go','data-page="salon"','small','arrow')}</div><div class="table-scroll"><table><thead><tr><th>Pedido</th><th>Estado</th><th>Total</th><th>Tiempo</th></tr></thead><tbody>${active.map(o=>`<tr><td><strong>${h(tableName(o))}</strong><small>#${o.id} · ${h(o.customer)}</small></td><td>${statePill(o.state)}</td><td class="amount">${money(total(o))}</td><td>${mins(o)} min</td></tr>`).join('')}</tbody></table></div></section></div><div class="stack"><section class="panel"><div class="panel-header"><h2>Conviene reponer</h2>${pill(low.length+' insumos','orange')}</div><div class="panel-body">${low.map(i=>`<div class="info-row"><div><strong>${h(i.name)}</strong><p class="subtle">Mínimo ${i.min} ${i.unit}</p></div><strong style="color:var(--orange)">${stock(state,i.id)} ${i.unit}</strong></div>`).join('')||'<p class="subtle">Todos los insumos tienen stock suficiente.</p>'}<div class="gap-top">${btn('Revisar inventario','go','data-page="inventario"','full','box')}</div></div></section><section class="panel"><div class="panel-header"><h2>Actividad reciente</h2>${icon('clock')}</div><div class="panel-body"><ul class="timeline">${state.audit.slice(-5).reverse().map(a=>`<li><strong>${h(a.entity)} · ${h(a.record)}</strong><p>${h(a.detail)}</p><small>${time(a.at)} · ${h(a.actor)}</small></li>`).join('')}</ul></div></section></div></div>`;}
function reservas(){const rows=state.reservations.filter(r=>!query||(r.name+' '+r.date).toLowerCase().includes(query.toLowerCase()));return head('Un lugar para cada ocasión','Organiza las próximas visitas, sin cruzar horarios.',btn('Nueva reserva','new-reservation','','primary','plus'))+`<div class="section-toolbar">${search('Buscar nombre o fecha...')}<span class="subtle">${state.reservations.filter(r=>['CONFIRMADA','PENDIENTE'].includes(r.state)).length} reservas pendientes</span></div><div class="cards-grid">${rows.map(r=>`<article class="record-card"><div class="record-head"><div><h3>${h(r.name)}</h3><p>${h(r.phone)}</p></div>${statePill(r.state)}</div><div class="info-row"><span>Fecha y horario</span><strong>${date(r.date)} · ${h(r.start)}–${h(r.end)}</strong></div><div class="info-row"><span>Mesa / personas</span><strong>Mesa ${String(r.table).padStart(2,'0')} · ${r.guests} personas</strong></div>${r.note?`<div class="gap-top">${note(h(r.note))}</div>`:''}<div class="card-actions">${['CONFIRMADA','PENDIENTE'].includes(r.state)?`${r.state==='PENDIENTE'?btn('Confirmar','reservation-state',`data-id="${r.id}" data-state="CONFIRMADA"`,'small','check'):''}${btn('Recibir clientes','reservation-state',`data-id="${r.id}" data-state="ATENDIDA"`,'small primary','users')}${btn('Cancelar','confirm-reservation-cancel',`data-id="${r.id}"`,'small ghost')}`:''}</div></article>`).join('')||empty('Sin reservas','No encontramos reservas para esta búsqueda.','calendar')}</div>`;}
function delivery(){const orders=state.orders.filter(o=>o.type==='DELIVERY'&&!o.closedAt&&o.state!=='CANCELADO');return head('De tu cocina a su puerta','Prepara, despacha y sigue cada entrega.',btn('Nuevo delivery','new-order','data-type="DELIVERY"','primary','plus'))+`<div class="cards-grid">${orders.map(o=>`<article class="record-card"><div class="record-head"><div><h3>Pedido #${o.id}</h3><p>${h(o.customer)} · ${h(o.phone)}</p></div>${statePill(o.deliveryState)}</div><p class="address">${icon('pin')}${h(o.address)}</p><div class="info-row"><span>Preparación</span>${statePill(o.state)}</div><div class="info-row"><span>Repartidor</span><strong>${h(o.courier)||'Por asignar'}</strong></div><div class="info-row"><span>Saldo por cobrar</span><strong>${money(balance(state,o))}</strong></div><div class="card-actions">${o.deliveryState==='PENDIENTE'?btn('Despachar','dispatch',`data-id="${o.id}"`,'small primary','bike'):o.deliveryState==='EN_RUTA'?btn('Confirmar entrega','delivery-delivered',`data-id="${o.id}"`,'small primary','check'):btn('Cerrar pedido','close-order',`data-id="${o.id}"`,'small primary','check')}${btn('Ver pedido','select-order',`data-id="${o.id}"`,'small','arrow')}</div></article>`).join('')||`<div class="panel">${empty('Todas las entregas, al día','Crea un nuevo pedido cuando llegue la siguiente orden.','bike')}</div>`}</div><div class="gap-top">${note('Este prototipo registra el estado y el repartidor. El seguimiento GPS y las integraciones con plataformas de delivery no están conectados.')}</div>`;}
function caja(){const pending=openOrders(state).filter(o=>total(o)>0), cash=expectedCash(state),session=state.session;const payments=state.payments.slice().reverse();return head('Cada cobro, en su lugar','Controla el efectivo, los pagos y el cierre de tu turno.',session.state==='ABIERTA'?btn('Movimiento de caja','cash-movement','','','plus')+btn('Cerrar caja','close-cash','','primary','wallet'):btn('Abrir caja','open-cash','','primary','wallet'))+`<div class="two-col"><div class="stack"><section class="panel"><div class="panel-header"><div><h2>Cuentas en servicio</h2><p>Admite pagos parciales y varios métodos por cuenta</p></div>${pill(pending.length+' pedidos','green')}</div><div class="table-scroll"><table><thead><tr><th>Pedido</th><th>Total</th><th>Saldo</th><th>Acción</th></tr></thead><tbody>${pending.map(o=>`<tr><td><strong>${h(tableName(o))} · #${o.id}</strong><small>${h(o.customer)}</small></td><td>${money(total(o))}</td><td class="amount">${money(balance(state,o))}</td><td>${balance(state,o)>0?btn('Cobrar','pay',`data-id="${o.id}"`,'small primary','wallet'):btn('Cerrar pedido','close-order',`data-id="${o.id}"`,'small','check')}</td></tr>`).join('')||'<tr><td colspan="4">No hay cuentas pendientes.</td></tr>'}</tbody></table></div></section><section class="panel"><div class="panel-header"><div><h2>Historial de cobros</h2><p>Los cobros se conservan; las devoluciones se registran por separado</p></div>${icon('receipt')}</div><div class="table-scroll"><table><thead><tr><th>Operación</th><th>Método</th><th>Importe</th><th></th></tr></thead><tbody>${payments.map(p=>{const ref=state.refunds.filter(r=>r.payment===p.id).reduce((s,r)=>s+r.amount,0);return`<tr><td><strong>Pedido #${p.order}</strong><small>${date(p.at)} · ${time(p.at)} · Cuenta ${p.account}</small>${ref?`<small>Devuelto: ${money(ref)}</small>`:''}</td><td>${pill(p.method,p.method==='EFECTIVO'?'green':'blue')}</td><td class="amount">${money(p.amount)}</td><td>${ref<p.amount?btn('Devolver','refund',`data-id="${p.id}"`,'small ghost','restore'):pill('Devuelto')}</td></tr>`;}).join('')}</tbody></table></div></section></div><div class="stack"><section class="cash-hero"><div class="inline-actions" style="justify-content:space-between"><div class="eyebrow">CAJA PRINCIPAL · TURNO ${session.id}</div>${pill(session.state==='ABIERTA'?'Abierta':'Cerrada')}</div><h2>${money(cash)}</h2><p>Efectivo esperado en caja</p><div class="cash-hero-footer"><span>${h(session.actor)}</span><span>Desde ${time(session.openedAt)}</span></div></section><section class="panel"><div class="panel-header"><h2>Resumen del turno</h2>${icon('wallet')}</div><div class="panel-body"><div class="info-row"><span>Fondo inicial</span><strong>${money(session.opening)}</strong></div>${['EFECTIVO','YAPE','PLIN','TARJETA','TRANSFERENCIA'].map(method=>`<div class="info-row"><span>${method.charAt(0)+method.slice(1).toLowerCase()}</span><strong>${money(state.payments.filter(p=>p.session===session.id&&p.method===method).reduce((sum,p)=>sum+p.amount,0))}</strong></div>`).join('')}<div class="info-row"><span>Devoluciones en efectivo</span><strong>− ${money(state.refunds.filter(r=>r.session===session.id&&r.method==='EFECTIVO').reduce((a,r)=>a+r.amount,0))}</strong></div><div class="info-row"><span>Movimientos netos de efectivo</span><strong>${money(state.cashMovements.filter(m=>m.session===session.id).reduce((a,m)=>a+m.amount,0))}</strong></div>${session.state==='CERRADA'?`<div class="info-row"><span>Efectivo contado</span><strong>${money(session.counted)}</strong></div><div class="info-row"><span>Diferencia</span><strong>${money(session.difference)}</strong></div>`:''}</div></section>${note('Yape, Plin, tarjetas y transferencias suman a los cobros, pero no al efectivo esperado. No se realizan cargos reales.')}<section class="panel"><div class="panel-header"><h2>Entradas y salidas de caja</h2></div><div class="panel-body">${state.cashMovements.filter(m=>m.session===session.id).slice().reverse().map(m=>`<div class="info-row"><div><strong>${h(m.reason)}</strong><p class="subtle">${time(m.at)} · ${h(m.actor)}</p></div><strong>${money(m.amount)}</strong></div>`).join('')||'<p class="subtle">Sin movimientos manuales en este turno.</p>'}</div></section></div></div>`;}
function inventario(){const rows=state.ingredients.filter(i=>i.es_activo&&(i.name+' '+i.code).toLowerCase().includes(query.toLowerCase())),low=state.ingredients.filter(i=>stock(state,i.id)<i.min);return head('Lo que necesitas para cocinar','Existencias calculadas a partir de cada entrada y salida.',btn('Registrar movimiento','movement','','primary','plus'),'CONTROL DE EXISTENCIAS')+`<div class="metrics">${metric('Insumos registrados',state.ingredients.length,'Almacén principal','box')}${metric('Por reponer',low.length,'Stock menor al mínimo','cart','orange')}${metric('Movimientos',state.movements.length,'Kardex de demostración','clock','blue')}${metric('Valor referencial',money(Math.round(state.ingredients.reduce((a,i)=>a+stock(state,i.id)*i.cost,0))),'Stock × costo de referencia','wallet')}</div><div class="section-toolbar">${search('Buscar insumo o código...')}<span class="subtle">Almacén principal · ${h(state.settings.branch)}</span></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Insumo</th><th>Existencia</th><th>Mínimo</th><th>Disponibilidad</th><th>Historial</th></tr></thead><tbody>${rows.map(i=>{const q=stock(state,i.id),low=q<i.min;return`<tr><td><strong>${h(i.name)}</strong><small>${h(i.code)} · Unidad base: ${h(i.unit)}</small></td><td class="amount">${q.toLocaleString('es-PE',{maximumFractionDigits:3})} ${i.unit}<div class="percentage ${low?'low':''}"><span style="width:${Math.min(100,q/i.min*50)}%"></span></div></td><td>${i.min} ${i.unit}</td><td>${pill(low?'Por reponer':'Stock suficiente',low?'orange':'green')}</td><td>${btn('Ver kardex','kardex',`data-id="${i.id}"`,'small ghost','clock')}</td></tr>`;}).join('')}</tbody></table></div><div class="table-summary"><span>${rows.length} insumos</span><span>Los movimientos confirmados conservan su historial</span></div></section>`;}
function compras(){return head('Abastece tu próximo servicio','Registra tus compras y recibe la mercadería en el almacén.',btn('Nueva compra','new-purchase','','primary','plus'),'COMPRAS Y PROVEEDORES')+`<section class="panel"><div class="table-scroll"><table><thead><tr><th>Compra</th><th>Proveedor</th><th>Insumos</th><th>Total</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${state.purchases.slice().reverse().map(c=>`<tr><td><strong>${h(c.reference)}</strong><small>${date(c.at)} · ${time(c.at)}</small></td><td>${h(state.suppliers.find(s=>s.id===c.supplier)?.name)}</td><td>${c.lines.length} líneas</td><td class="amount">${money(Math.round(c.lines.reduce((s,l)=>s+l.qty*l.cost,0)))}</td><td>${statePill(c.state)}</td><td><div class="inline-actions">${ib('Ver detalle de compra','purchase-detail','eye',`data-id="${c.id}"`)}${c.state==='BORRADOR'?btn('Recibir','receive-purchase',`data-id="${c.id}"`,'small primary','box')+ib('Cancelar compra','cancel-purchase','close',`data-id="${c.id}"`):''}</div></td></tr>`).join('')||'<tr><td colspan="6">Aún no has registrado compras.</td></tr>'}</tbody></table></div></section><div class="gap-top">${note('Un borrador no cambia las existencias. Al recibirlo, se registra una entrada por cada insumo. Esta operación no puede repetirse sobre la misma compra.')}</div>`;}
function carta(){const cats=['Todos','Fondos','Entradas','Bebidas','Postres','Adicionales'];const rows=state.products.filter(p=>p.es_activo!==showInactive&&(category==='Todos'||p.category===category)&&(p.name+' '+p.code).toLowerCase().includes(query.toLowerCase()));return head('Una carta con identidad','Platos, precios y recetas que dan vida a tu restaurante.',btn(showInactive?'Ver activos':'Ver dados de baja','inactive','','',showInactive?'eye':'clock')+btn('Nuevo producto','edit-product','','primary','plus'),'CARTA Y PRODUCCIÓN')+`<div class="section-toolbar"><div class="chips">${cats.map(c=>`<button class="filter-chip ${category===c?'active':''}" data-action="category" data-category="${c}">${c}</button>`).join('')}</div>${search('Buscar en la carta...')}</div>${showInactive?`<div style="margin-bottom:18px">${note('Estos productos conservan sus códigos, recetas y ventas históricas. Puedes restaurar el mismo registro.')}</div>`:''}<div class="cards-grid">${rows.map(p=>`<article class="product-card ${p.es_activo?'':'inactive'}"><div class="product-visual" data-cat="${h(p.category)}">${icon(p.category==='Bebidas'?'drink':p.category==='Postres'?'cake':'plate')}${pill(!p.es_activo?'Baja lógica':p.disponible?'Disponible':'Pausado',p.es_activo&&p.disponible?'green':'orange')}</div><div class="product-card-content"><h3>${h(p.name)}</h3><div class="product-card-meta">${h(p.code)} · ${h(p.category)} · ${h(p.station)}</div><div class="product-card-footer"><strong>${money(p.price)}</strong><div>${ib('Ver receta y auditoría','product-detail','book',`data-id="${p.id}"`)}${p.es_activo?`${ib('Editar producto','edit-product','edit',`data-id="${p.id}"`)}${ib(p.disponible?'Pausar disponibilidad':'Activar disponibilidad','availability',p.disponible?'pause':'play',`data-id="${p.id}"`)}`:ib('Restaurar producto','restore','restore',`data-entity="products" data-id="${p.id}"`)}</div></div></div></article>`).join('')||empty('Sin productos','Prueba con otra categoría o búsqueda.','book')}</div>`;}
function comprobantes(){return head('Comprobantes, con trazabilidad','Consulta los documentos de tus pedidos cobrados.',btn('Simular comprobante','invoice','','primary','plus'),'VENTAS')+`<div style="margin-bottom:20px">${note('Documentos de demostración, sin validez tributaria. No se emiten comprobantes electrónicos ni se envía información a SUNAT.','orange')}</div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Documento</th><th>Cliente</th><th>Pedido</th><th>Total</th><th>Estado</th><th></th></tr></thead><tbody>${state.invoices.slice().reverse().map(i=>`<tr><td><strong>${h(i.number)}</strong><small>${h(i.type)} · ${date(i.at)}</small></td><td>${h(i.customer)}<small>${h(i.document)||'Sin documento'}</small></td><td>#${i.order}</td><td class="amount">${money(i.amount)}</td><td>${statePill(i.state)}</td><td>${btn('Ver documento','receipt',`data-id="${i.id}"`,'small','eye')}</td></tr>`).join('')}</tbody></table></div></section>`;}
function contactos(){const rows=state[contactType].filter(r=>r.es_activo!==showInactive&&(r.name+' '+r.document).toLowerCase().includes(query.toLowerCase()));return head('Las personas detrás del negocio','Mantén tus relaciones y su historial en un solo lugar.',btn(showInactive?'Ver activos':'Ver dados de baja','inactive','','','clock')+btn(contactType==='customers'?'Nuevo cliente':'Nuevo proveedor','edit-contact','','primary','plus'),'DIRECTORIO')+`<div class="section-toolbar"><div class="tabs">${[['customers','Clientes'],['suppliers','Proveedores']].map(([key,text])=>`<button class="tab ${contactType===key?'active':''}" data-action="contact-type" data-type="${key}">${text}</button>`).join('')}</div>${search('Buscar nombre o documento...')}</div><section class="panel"><div class="table-scroll"><table><thead><tr><th>${contactType==='customers'?'Cliente':'Proveedor'}</th><th>Documento</th><th>Contacto</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${h(r.name)}</strong><small>Creado por ${h(r.creado_por)}</small></td><td>${h(r.document)}</td><td>${h(r.phone)}<small>${h(r.email)}</small></td><td>${pill(r.es_activo?'Activo':'Baja lógica',r.es_activo?'green':'red')}</td><td><div class="inline-actions">${ib('Ver auditoría del registro','record-meta','clock',`data-entity="${contactType}" data-id="${r.id}"`)}${r.es_activo?ib('Editar contacto','edit-contact','edit',`data-id="${r.id}"`)+ib('Dar de baja','soft-delete','trash',`data-entity="${contactType}" data-id="${r.id}"`):ib('Restaurar contacto','restore','restore',`data-entity="${contactType}" data-id="${r.id}"`)}</div></td></tr>`).join('')||'<tr><td colspan="5">No se encontraron registros.</td></tr>'}</tbody></table></div><div class="table-summary"><span>${rows.length} registros</span><span>Los documentos se conservan únicos, incluso después de la baja</span></div></section>`;}
function usuarios(){return head('Tu equipo, bien organizado','Roles y trazabilidad para cada integrante.',btn(showInactive?'Ver activos':'Ver dados de baja','inactive','','','clock'),'EQUIPO Y ACCESOS')+`<div class="user-list">${state.users.filter(u=>u.es_activo!==showInactive).map(u=>`<article class="user-card"><div class="user-card-top"><div class="avatar">${h(u.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</div><div><h3>${h(u.name)} ${u.id===1?'<span class="subtle">· Tú</span>':''}</h3><p>@${h(u.username)} · ${h(state.settings.branch)}</p></div></div><div class="card-actions">${pill(u.role,u.es_activo?'green':'red')}<div class="inline-actions">${ib('Ver auditoría del usuario','record-meta','clock',`data-entity="users" data-id="${u.id}"`)}${u.id!==1?(u.es_activo?ib('Cambiar rol','user-role','edit',`data-id="${u.id}"`)+ib('Dar de baja al usuario','soft-delete','trash',`data-entity="users" data-id="${u.id}"`):ib('Restaurar usuario','restore','restore',`data-entity="users" data-id="${u.id}"`)):''}</div></div></article>`).join('')}</div><div class="gap-top">${note('La sesión de demostración usa el perfil Administradora. Los cambios de rol ilustran el modelo; la autenticación y la autorización real requieren el backend.')}</div>`;}
function auditoria(){const rows=state.audit.slice().reverse().filter(a=>(a.entity+' '+a.record+' '+a.actor+' '+a.action+' '+a.detail).toLowerCase().includes(query.toLowerCase()));return head('Cada cambio tiene una historia','Quién hizo qué, sobre qué registro y en qué momento.',btn('Descargar historial','export-audit','','','download'),'TRAZABILIDAD')+`<div class="section-toolbar">${search('Buscar usuario, acción o registro...')}<span class="subtle">${rows.length} eventos · Historial de solo lectura</span></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Momento</th><th>Usuario</th><th>Registro</th><th>Acción</th><th>Detalle</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${date(a.at)}<small>${time(a.at)}</small></td><td><strong>${h(a.actor)}</strong></td><td>${h(a.entity)}<small>${h(a.record)}</small></td><td><span class="audit-action" style="color:${a.action==='BAJA LÓGICA'?'var(--red)':'var(--green)'}">${h(a.action)}</span></td><td class="audit-detail">${h(a.detail)}</td></tr>`).join('')||'<tr><td colspan="5">Sin resultados.</td></tr>'}</tbody></table></div></section>`;}
function configuracion(){return head('A tu manera de trabajar','Los detalles que hacen que el sistema sea tuyo.','','CONFIGURACIÓN')+`<div class="two-col"><div class="stack"><section class="panel"><div class="panel-header"><h2>Tu restaurante</h2>${icon('store')}</div><div class="panel-body"><form data-form="settings" class="settings-form"><div class="form-grid">${input('Nombre comercial','name',state.settings.name,'text','required',true)}${input('Sucursal','branch',state.settings.branch,'text','required',true)}${input('Dirección','address',state.settings.address,'text','',true)}</div><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Guardar datos ${icon('check')}</button></form></div></section><section class="panel"><div class="panel-header"><h2>Mesas y espacios</h2><span class="subtle">Salón principal y terraza</span></div><div class="table-scroll"><table><thead><tr><th>Mesa</th><th>Capacidad</th><th>Habilitada</th><th>Registro</th></tr></thead><tbody>${state.tables.map(t=>`<tr><td><strong>${h(t.name)}</strong><small>${h(t.zone)}</small></td><td>${t.capacity} personas</td><td><button class="toggle ${t.habilitada?'on':''}" data-action="table-enabled" data-id="${t.id}" aria-label="${t.habilitada?'Deshabilitar':'Habilitar'} ${t.name}" aria-pressed="${t.habilitada}" ${!t.es_activo?'disabled':''}></button></td><td><div class="inline-actions">${pill(t.es_activo?'Activo':'Inactivo',t.es_activo?'green':'red')}${t.es_activo?ib('Desactivar mesa','soft-delete','trash',`data-entity="tables" data-id="${t.id}"`):ib('Activar mesa','restore','restore',`data-entity="tables" data-id="${t.id}"`)}</div></td></tr>`).join('')}</tbody></table></div></section></div><div class="stack"><section class="panel"><div class="panel-header"><h2>Acerca del prototipo</h2>${icon('info')}</div><div class="panel-body"><div class="info-row"><span>Moneda</span><strong>Soles · PEN</strong></div><div class="info-row"><span>Datos</span><strong>Ejemplos locales</strong></div><div class="info-row"><span>Base de referencia</span><strong>PostgreSQL · 49 tablas</strong></div><div class="info-row"><span>Conexión al servidor</span><strong>No conectada</strong></div><div class="gap-top">${note('Los datos se guardan solo en este navegador. El prototipo permite validar pantallas y procesos antes de desarrollar la aplicación conectada a la base de datos.')}</div></div></section><section class="panel"><div class="panel-header"><h2>Control de registros</h2>${icon('shield')}</div><div class="panel-body"><div class="setting-block"><div><h3>Disponibilidad</h3><p>Pausa temporal de productos o habilitación de mesas.</p></div>${pill('Operación','green')}</div><div class="setting-block"><div><h3>Estado del negocio</h3><p>Preparación, pago, recepción o cancelación según el proceso.</p></div>${pill('Proceso','blue')}</div><div class="setting-block"><div><h3>Eliminación lógica</h3><p>Baja de maestros principales con motivo, usuario y fecha. Las mesas se desactivan y conservan su historial.</p></div>${pill('Registro','orange')}</div></div></section><section class="panel"><div class="panel-body"><h3 style="font-size:13px">Volver a empezar</h3><p class="subtle" style="margin:9px 0 15px">Restablece los ejemplos y elimina los cambios de esta demostración en tu navegador.</p>${btn('Restablecer demostración','reset','','danger','restore')}</div></section></div></div>`;}
const views={salon,cocina,dashboard,reservas,delivery,caja,inventario,compras,carta,comprobantes,contactos,usuarios,auditoria,configuracion};
function newOrder(type='SALON',table){const available=state.tables.filter(t=>t.es_activo&&t.habilitada&&!openOrders(state).some(o=>o.table===t.id));modal('Un nuevo pedido','Abre una mesa o registra una orden para llevar o enviar.',formStart('newOrder')+`<div class="form-grid">${select('Tipo de atención','type',['SALON','LLEVAR','DELIVERY'].map(v=>option(v,labels[v],type)).join(''),true)}<div class="field full" id="table-field">${select('Mesa','table',available.map(t=>option(t.id,t.name+' · '+t.capacity+' personas',table)).join(''))}</div>${input('Comensales','guests',1,'number','required min="1" max="50"')}${input('Cliente','customer','','text','placeholder="Público general"')}<div id="delivery-fields" class="field full" style="display:${type==='DELIVERY'?'block':'none'}">${input('Teléfono','phone','','tel')}${input('Dirección de entrega','address','','text')}</div></div>`+formEnd('Crear pedido'));refreshOrderFields(type);}
function refreshOrderFields(type){const t=document.querySelector('#table-field'),d=document.querySelector('#delivery-fields');if(t)t.style.display=type==='SALON'?'block':'none';if(d)d.style.display=type==='DELIVERY'?'block':'none';}
function addProduct(id){const o=orderById(id);pickedProduct=state.products.find(p=>p.es_activo&&p.disponible)?.id;modal('Algo bueno para la mesa',`Pedido #${o.id} · ${tableName(o)}`,formStart('addLine',`data-order="${o.id}"`)+`<label class="search" style="max-width:none">${icon('search')}<input type="search" id="product-search" placeholder="Buscar producto..." aria-label="Buscar producto"></label><div class="modal-products" id="product-picker">${productPicker('')}</div><div class="add-line-fields"><div class="form-grid">${input('Cantidad','qty',1,'number','required min="1" max="99"')}${select('Asignar a','account',o.accounts.map(a=>option(a,'Cuenta '+a,account||o.accounts[0])).join(''))}${textarea('Indicaciones para cocina (opcional)','note')}</div></div>`+formEnd('Agregar al pedido'),true);}
function productPicker(q){return state.products.filter(p=>p.es_activo&&p.disponible&&p.name.toLowerCase().includes(q.toLowerCase())).map(p=>`<button type="button" class="pick-product ${p.id===pickedProduct?'selected':''}" data-action="pick-product" data-id="${p.id}" aria-pressed="${p.id===pickedProduct}"><small>${h(p.category)}</small><strong>${h(p.name)}</strong><span>${money(p.price)}</span></button>`).join('')||'<p class="subtle">No hay productos disponibles que coincidan.</p>';}
function payModal(id){const o=orderById(id),accounts=o.accounts.filter(a=>balance(state,o,a)>0);if(!accounts.length){toast('El pedido ya está pagado.');return;}const a=accounts.includes(account)?account:accounts[0],due=balance(state,o,a);modal('Cobrar cuenta',`Pedido #${o.id} · ${tableName(o)}`,formStart('pay',`data-order="${o.id}"`)+`<div class="money-display"><span>Saldo de la cuenta</span><strong id="payment-balance">${money(due)}</strong></div><div class="form-grid">${select('Cuenta','account',accounts.map(v=>option(v,'Cuenta '+v,a)).join(''))}${select('Método de pago','method',['EFECTIVO','YAPE','PLIN','TARJETA','TRANSFERENCIA'].map(m=>option(m,m,'EFECTIVO')).join(''))}${input('Importe a aplicar (S/)','amount',(due/100).toFixed(2),'number','required min="0.01" step="0.01"')}${input('Efectivo recibido (S/)','received',(due/100).toFixed(2),'number','min="0" step="0.01"')}<div class="field full" id="reference-field" hidden>${input('Referencia de operación','reference','','text','placeholder="Número de operación o referencia"')}</div></div><div class="info-row" id="change-row"><span>Vuelto</span><strong id="payment-change">S/ 0.00</strong></div><div class="gap-top">${note('Puedes aplicar un importe parcial y registrar el resto con otro método. Al confirmar el primer pago, los consumos de este pedido quedan bloqueados.')}</div>`+formEnd('Confirmar cobro','accent'));}
function refreshPayment(){const f=modalRoot.querySelector('form[data-form="pay"]');if(!f)return;const d=new FormData(f),cash=d.get('method')==='EFECTIVO';const received=f.elements.received;received.closest('.field').style.display=cash?'flex':'none';document.querySelector('#reference-field').hidden=cash;document.querySelector('#change-row').style.display=cash?'flex':'none';document.querySelector('#payment-change').textContent=money(Math.max(0,toCents(d.get('received'))-toCents(d.get('amount'))));}
function splitModal(id){const o=orderById(id);modal('Dividir la cuenta','Selecciona los consumos completos para una nueva cuenta.',formStart('split',`data-order="${o.id}"`)+o.lines.filter(l=>l.state!=='CANCELADO').map(l=>`<label class="check-row"><input type="checkbox" name="lines" value="${l.id}"><span>${l.qty}× ${h(l.name)}<br><small>Cuenta ${l.account}</small></span><strong>${money(l.price*l.qty)}</strong></label>`).join('')+note('La división de una misma cantidad de producto en varias líneas queda para el backend. Aquí puedes mover líneas completas antes del primer cobro.')+formEnd('Crear cuenta separada'));}
function reservationModal(){modal('Una mesa para una próxima visita','Las reservas de una misma mesa no pueden cruzarse.',formStart('reservation')+`<div class="form-grid">${input('Nombre del cliente','name','','text','required')}${input('Teléfono','phone','','tel','required')}${input('Fecha','date',today(),'date',`required min="${today()}"`)}${select('Mesa','table',state.tables.filter(t=>t.es_activo&&t.habilitada).map(t=>option(t.id,t.name+' · '+t.capacity+' personas')).join(''))}${input('Hora de llegada','start','19:00','time','required')}${input('Hora de salida','end','20:30','time','required')}${input('Personas','guests',2,'number','required min="1" max="50"')}${textarea('Notas (opcional)','note')}</div>`+formEnd('Confirmar reserva'));}
function movementModal(){modal('Registrar movimiento de inventario','Un movimiento confirmado se corrige con otro movimiento.',formStart('movement')+`<div class="form-grid">${select('Insumo','item',state.ingredients.filter(i=>i.es_activo).map(i=>option(i.id,i.name+' · '+stock(state,i.id)+' '+i.unit+' disponibles')).join(''),true)}${select('Tipo de movimiento','type',[['AJUSTE_ENTRADA','Ajuste de entrada (+)'],['AJUSTE_SALIDA','Ajuste de salida (−)'],['MERMA','Merma (−)']].map(([v,l])=>option(v,l)).join(''))}${input('Cantidad en unidad base','qty',1,'number','required min="0.001" step="0.001"')}${textarea('Motivo del movimiento','reason','',true)}</div>`+formEnd('Confirmar movimiento'));}
function purchaseRow(){return`<div class="purchase-row"><label>Insumo / unidad base<select name="item">${state.ingredients.filter(i=>i.es_activo).map(i=>option(i.id,i.name+' ('+i.unit+')')).join('')}</select></label><label>Cantidad<input name="qty" type="number" value="1" min="0.001" step="0.001" required></label><label>Costo unit. S/<input name="cost" type="number" value="28.00" min="0" step="0.01" required></label>${ib('Quitar insumo','remove-purchase-line','close')}</div>`;}
function purchaseModal(){modal('Registrar una compra','Guárdala como borrador y recibe los insumos cuando lleguen.',formStart('purchase')+`<div class="form-grid">${select('Proveedor','supplier',state.suppliers.filter(s=>s.es_activo).map(s=>option(s.id,s.name)).join(''))}${input('Comprobante / referencia','reference','','text','required placeholder="F001-002459"')}</div><div id="purchase-lines" class="gap-top">${purchaseRow()}</div><div class="gap-top">${btn('Agregar insumo','add-purchase-line','','small','plus')}</div>`+formEnd('Guardar borrador'),true);}
function purchaseDetail(id){const c=state.purchases.find(c=>c.id===+id);modal(h(c.reference),`${state.suppliers.find(s=>s.id===c.supplier)?.name} · ${labels[c.state]}`,`<div class="table-scroll"><table><thead><tr><th>Insumo</th><th>Cantidad</th><th>Costo unit.</th><th>Total</th></tr></thead><tbody>${c.lines.map(l=>{const i=state.ingredients.find(i=>i.id===l.item);return`<tr><td>${h(i.name)}</td><td>${l.qty} ${i.unit}</td><td>${money(l.cost)}</td><td>${money(Math.round(l.cost*l.qty))}</td></tr>`;}).join('')}</tbody></table></div><div class="money-display gap-top"><span>Total de compra</span><strong>${money(Math.round(c.lines.reduce((s,l)=>s+l.qty*l.cost,0)))}</strong></div><div class="modal-actions">${btn('Cerrar','close-modal')}${c.state==='BORRADOR'?btn('Recibir en almacén','receive-purchase',`data-id="${c.id}"`,'primary','box'):''}</div>`,true);}
function editProduct(id){const p=state.products.find(p=>p.id===+id)||{name:'',code:'',category:'Fondos',price:0,station:'Cocina',type:'PREPARADO'};modal(id?'Editar producto':'Un nuevo sabor en la carta','Cambiar el precio no altera los consumos históricos.',formStart('saveProduct',id?`data-id="${id}"`:'')+`<div class="form-grid">${input('Nombre del producto','name',p.name,'text','required',true)}${input('Código único','code',p.code,'text','required placeholder="PL-013"')}${input('Precio de venta (S/)','price',p.price?p.price/100:'','number','required min="0.01" step="0.01"')}${select('Categoría','category',['Fondos','Entradas','Bebidas','Postres','Adicionales'].map(c=>option(c,c,p.category)).join(''))}${select('Estación','station',['Cocina','Barra'].map(c=>option(c,c,p.station)).join(''))}${select('Tipo de producto','type',['PREPARADO','REVENTA','ADICIONAL','SERVICIO'].map(c=>option(c,c,p.type)).join(''),true)}</div>`+formEnd('Guardar producto'));}
function metaContent(r){return`<div class="info-row"><span>Creado por</span><strong>${h(r.creado_por)}</strong></div><div class="info-row"><span>Creado el</span><strong>${date(r.creado_en)} · ${time(r.creado_en)}</strong></div><div class="info-row"><span>Actualizado por</span><strong>${h(r.actualizado_por)}</strong></div><div class="info-row"><span>Última actualización</span><strong>${date(r.actualizado_en)} · ${time(r.actualizado_en)}</strong></div><div class="info-row"><span>Registro activo</span>${pill(r.es_activo?'Sí':'No',r.es_activo?'green':'red')}</div>${!r.es_activo?`<div class="info-row"><span>Eliminado por</span><strong>${h(r.eliminado_por)}</strong></div><div class="info-row"><span>Fecha de baja</span><strong>${date(r.eliminado_en)} · ${time(r.eliminado_en)}</strong></div><div class="gap-top">${note('Motivo: '+h(r.motivo_eliminacion),'orange')}</div>`:''}`;}
function productDetail(id){const p=state.products.find(p=>p.id===+id),recipe=state.recipes[p.id]||[];modal(h(p.name),`${p.code} · ${p.type} · ${p.station}`,`<div class="inline-actions" style="justify-content:space-between;margin-bottom:20px">${pill(p.disponible?'Disponible en carta':'Pausado en carta',p.disponible?'green':'orange')}<strong>${money(p.price)}</strong></div><h3 style="font-size:13px;margin-bottom:12px">Receta de referencia · 1 porción</h3>${recipe.length?`<div class="table-scroll"><table><thead><tr><th>Insumo</th><th>Cantidad base</th></tr></thead><tbody>${recipe.map(r=>{const i=state.ingredients.find(i=>i.id===r.item);return`<tr><td>${h(i.name)}</td><td>${r.qty} ${i.unit}</td></tr>`;}).join('')}</tbody></table></div>`:note('Este producto no tiene una receta de ejemplo. No genera consumo automático de insumos.')}<h3 style="font-size:13px;margin:25px 0 8px">Trazabilidad del registro</h3>${metaContent(p)}<div class="modal-actions">${btn('Cerrar','close-modal')}${p.es_activo?btn('Dar de baja','soft-delete',`data-entity="products" data-id="${p.id}"`,'danger','trash'):btn('Restaurar producto','restore',`data-entity="products" data-id="${p.id}"`,'primary','restore')}</div>`);}
function contactModal(id){const r=state[contactType].find(r=>r.id===+id)||{};modal(id?'Editar contacto':contactType==='customers'?'Nuevo cliente':'Nuevo proveedor','El documento identifica de forma única al contacto.',formStart('saveContact',`data-entity="${contactType}" ${id?`data-id="${id}"`:''}`)+`<div class="form-grid">${input('Nombre / razón social','name',r.name||'','text','required',true)}${input(contactType==='suppliers'?'RUC (11 dígitos)':'Documento','document',r.document||'','text',contactType==='suppliers'?'required inputmode="numeric" pattern="[0-9]{11}" maxlength="11"':'required')}${input('Teléfono','phone',r.phone||'','tel')}${input('Correo electrónico','email',r.email||'','email','',true)}</div>`+formEnd('Guardar contacto'));}
function invoiceModal(){const orders=state.orders.filter(o=>total(o)>0&&balance(state,o)===0&&o.state!=='CANCELADO'&&!state.invoices.some(i=>i.order===o.id));if(!orders.length){modal('Simular un comprobante','Comienza con un pedido completamente cobrado.',empty('No hay pedidos disponibles','Cobra un pedido que todavía no tenga un comprobante simulado.','receipt',btn('Ir a caja','go','data-page="caja"','primary','wallet')));return;}modal('Simular comprobante','Documento de ejemplo, sin validez tributaria.',formStart('invoice')+`<div class="form-grid">${select('Pedido cobrado','order',orders.map(o=>option(o.id,'#'+o.id+' · '+o.customer+' · '+money(total(o)))).join(''),true)}${select('Tipo de comprobante','type',['Boleta','Factura'].map(t=>option(t,t)).join(''))}${input('Documento / RUC','document','','text')}${input('Cliente / razón social','customer','','text','placeholder="Usar el cliente del pedido"',true)}</div><div class="gap-top">${note('Esta acción solo crea una vista previa. La configuración tributaria vigente y el envío real a SUNAT requieren implementación y validación adicionales.','orange')}</div>`+formEnd('Crear documento de ejemplo'));}
function receiptModal(id){const i=state.invoices.find(i=>i.id===+id),o=orderById(i.order),lines=i.lines||o.lines;modal('Vista del comprobante','Solo demostración · sin validez tributaria',`<article class="receipt"><div class="receipt-head"><h3>${h(state.settings.name)}</h3><p>${h(state.settings.branch)}<br>${h(state.settings.address)}<br><strong>${h(i.type).toUpperCase()} DE DEMOSTRACIÓN</strong><br>${h(i.number)}</p></div><div class="receipt-line"><span>Cliente</span><strong>${h(i.customer)}</strong></div><div class="receipt-line"><span>Documento</span><span>${h(i.document)||'—'}</span></div><div class="receipt-line"><span>Fecha</span><span>${date(i.at)} · ${time(i.at)}</span></div><div style="border-top:1px dashed #d5dfc9;margin-top:10px;padding-top:10px">${lines.filter(l=>l.state!=='CANCELADO').map(l=>`<div class="receipt-line"><span>${l.qty}× ${h(l.name)}</span><strong>${money(l.qty*l.price)}</strong></div>`).join('')}</div><div class="receipt-total"><span>Total</span><strong>${money(i.amount)}</strong></div><p class="receipt-warning">DOCUMENTO DE EJEMPLO<br>No enviado a SUNAT · No constituye comprobante de pago.<br>Sin desglose tributario real.</p></article><div class="modal-actions">${btn('Cerrar','close-modal')}${btn('Imprimir ejemplo','print','','primary','receipt')}</div>`);}
function helpModal(){modal('Conoce tu restaurante, en acción','Un recorrido breve por Mesa.',`<p class="subtle">Este prototipo convierte el modelo de base de datos en una experiencia para el equipo del restaurante. Prueba los flujos con libertad: todos los registros son de ejemplo.</p><div class="welcome-steps"><div class="welcome-step"><b>01</b><h3>Abre una mesa</h3><p>Agrega productos y envía la comanda a cocina.</p></div><div class="welcome-step"><b>02</b><h3>Prepara y sirve</h3><p>Avanza cada producto por sus etapas. La receta consume insumos.</p></div><div class="welcome-step"><b>03</b><h3>Cobra y cierra</h3><p>Divide cuentas, combina pagos y libera la mesa al terminar.</p></div></div><div class="gap-top">${note('También puedes recibir compras, revisar el kardex, gestionar reservas y probar la baja lógica desde Carta o Contactos. Cada cambio queda en Auditoría.')}</div><div class="gap-top">${note('No hay conexión a PostgreSQL, autenticación real, cobros bancarios ni emisión tributaria. Los ejemplos se guardan en este navegador. Puedes restablecerlos en Configuración.','orange')}</div><div class="modal-actions">${btn('Empezar en el salón','go','data-page="salon"','primary','arrow')}</div>`,true);}
const toCents=v=>Math.round(Number(v)*100);
function navigate(next){closeModal();query='';showInactive=false;page=next;if(location.hash!=='#'+next)location.hash=next;else render();window.scrollTo?.({top:0,behavior:'instant'});}
function handleClick(event){const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const d=b.dataset,id=d.id;switch(d.action){
 case 'menu':document.querySelector('#sidebar').classList.toggle('open');break;
 case 'close-modal':closeModal();break;
 case 'help':helpModal();break;
 case 'go':navigate(d.page);break;
 case 'zone':zone=d.zone;render();break;
 case 'station':station=d.station;render();break;
 case 'category':category=d.category;render();break;
 case 'inactive':showInactive=!showInactive;render();break;
 case 'contact-type':contactType=d.type;showInactive=false;query='';render();break;
 case 'table':{const t=state.tables.find(t=>t.id===+id);if(!t.es_activo||!t.habilitada){toast('Esta mesa no está habilitada. Puedes gestionarla en Configuración.');break;}const o=openOrders(state).find(o=>o.table===t.id);if(o){selected=o.id;account=0;render();}else newOrder('SALON',id);break;}
 case 'select-order':{const o=orderById(id);selected=+id;account=0;zone=o.table?state.tables.find(t=>t.id===o.table).zone:'Para llevar';navigate('salon');break;}
 case 'new-order':newOrder(d.type||'SALON');break;
 case 'add-product':addProduct(id);break;
 case 'pick-product':pickedProduct=+id;modalRoot.querySelectorAll('.pick-product').forEach(el=>{const active=+el.dataset.id===pickedProduct;el.classList.toggle('selected',active);el.setAttribute('aria-pressed',String(active));});break;
 case 'remove-line':perform('removeLine',{order:d.order,line:d.line},'Producto retirado del pedido.');break;
 case 'send':perform('send',{order:id},'Comanda enviada. Ya aparece en Cocina.');break;
 case 'line-state':perform('lineState',{order:d.order,line:d.line,state:d.state},d.state==='PREPARACION'?'Preparación iniciada; consumo de receta registrado.':d.state==='LISTO'?'Producto listo para servir.':'Producto entregado.');break;
 case 'split':splitModal(id);break;
 case 'pay':payModal(id);break;
 case 'close-order':perform('closeOrder',{order:id},'Pedido cerrado. La mesa ya está disponible.');break;
 case 'cancel-order':modal('Cancelar pedido #'+id,'Los consumos de inventario ya confirmados conservarán su historial.',formStart('cancelOrder',`data-order="${id}"`)+textarea('Motivo de cancelación','reason','',true)+formEnd('Cancelar pedido','danger'));break;
 case 'new-reservation':reservationModal();break;
 case 'reservation-state':{const r=perform('reservationState',{id,state:d.state},d.state==='ATENDIDA'?'Clientes recibidos. Pedido abierto.':'Reserva actualizada.');if(r?.result){selected=r.result;account=0;const o=orderById(selected);zone=state.tables.find(t=>t.id===o.table).zone;navigate('salon');}break;}
 case 'confirm-reservation-cancel':modal('Cancelar reserva','La reserva conservará su historial.',formStart('reservationState',`data-id="${id}"`)+`<input type="hidden" name="state" value="CANCELADA"><p class="subtle">¿Quieres cancelar la reserva de ${h(state.reservations.find(r=>r.id===+id).name)}?</p>`+formEnd('Cancelar reserva','danger'));break;
 case 'dispatch':modal('Despachar pedido #'+id,'Todos los productos deben estar listos.',formStart('deliveryState',`data-order="${id}"`)+`<input type="hidden" name="state" value="EN_RUTA">`+input('Nombre del repartidor','courier','','text','required')+formEnd('Enviar a ruta'));break;
 case 'delivery-delivered':perform('deliveryState',{order:id,state:'ENTREGADO'},'Entrega confirmada.');break;
 case 'cash-movement':modal('Entrada o salida de efectivo','Registra movimientos que no corresponden a un cobro.',formStart('cashMovement')+`<div class="form-grid">${select('Tipo','type',option('ENTRADA','Entrada de efectivo')+option('SALIDA','Salida de efectivo'))}${input('Importe (S/)','amount','','number','required min="0.01" step="0.01"')}${textarea('Motivo','reason','',true)}</div>`+formEnd('Registrar movimiento'));break;
 case 'close-cash':modal('Cerrar turno de caja','Cuenta el efectivo físico antes de confirmar.',formStart('closeCash')+`<div class="money-display"><span>Efectivo esperado</span><strong>${money(expectedCash(state))}</strong></div>`+input('Efectivo contado (S/)','counted','','number','required min="0" step="0.01"')+note('Los pedidos abiertos pueden continuar en el siguiente turno. El cierre conserva el efectivo esperado, el contado y la diferencia.')+formEnd('Confirmar cierre'));break;
 case 'open-cash':modal('Abrir un nuevo turno','El fondo inicial será la base del efectivo esperado.',formStart('openCash')+input('Fondo inicial (S/)','opening','200.00','number','required min="0" step="0.01"')+formEnd('Abrir caja'));break;
 case 'refund':{const p=state.payments.find(p=>p.id===+id),remaining=p.amount-state.refunds.filter(r=>r.payment===p.id).reduce((a,r)=>a+r.amount,0);modal('Registrar devolución',`Pedido #${p.order} · ${p.method}`,formStart('refund',`data-payment="${p.id}"`)+`<div class="money-display"><span>Disponible para devolver</span><strong>${money(remaining)}</strong></div>`+input('Importe de devolución (S/)','amount','','number',`required min="0.01" max="${remaining/100}" step="0.01"`)+textarea('Motivo de devolución','reason','',true)+note('El cobro original se conserva. Esta operación registra la devolución y no reabre automáticamente el saldo ni repone inventario.')+formEnd('Confirmar devolución'));break;}
 case 'movement':movementModal();break;
 case 'kardex':{const i=state.ingredients.find(i=>i.id===+id);modal('Kardex · '+h(i.name),`Existencia actual: ${stock(state,i.id)} ${i.unit}`,`<div class="table-scroll"><table><thead><tr><th>Momento</th><th>Movimiento</th><th>Cantidad</th><th>Referencia</th></tr></thead><tbody>${state.movements.filter(m=>m.item===i.id).slice().reverse().map(m=>`<tr><td>${date(m.at)}<small>${time(m.at)}</small></td><td>${h(m.type.replaceAll('_',' '))}</td><td class="amount" style="color:${m.qty<0?'var(--orange)':'var(--green)'}">${m.qty>0?'+':''}${m.qty} ${i.unit}</td><td class="audit-detail">${h(m.note)}</td></tr>`).join('')}</tbody></table></div><div class="modal-actions">${btn('Cerrar','close-modal')}</div>`,true);break;}
 case 'new-purchase':purchaseModal();break;
 case 'add-purchase-line':document.querySelector('#purchase-lines').insertAdjacentHTML('beforeend',purchaseRow());break;
 case 'remove-purchase-line':if(document.querySelectorAll('.purchase-row').length>1)b.closest('.purchase-row').remove();else toast('La compra necesita al menos un insumo.');break;
 case 'purchase-detail':purchaseDetail(id);break;
 case 'receive-purchase':{const c=state.purchases.find(c=>c.id===+id);modal('Recibir mercadería','Confirma que las cantidades de la compra llegaron al almacén.',formStart('receivePurchase',`data-id="${id}"`)+`<p class="subtle">${h(c.reference)} · ${c.lines.length} insumos · ${money(Math.round(c.lines.reduce((s,l)=>s+l.cost*l.qty,0)))}</p><div class="gap-top">${note('La recepción generará los movimientos de ingreso. Luego, la compra quedará bloqueada para recibirla otra vez.')}</div>`+formEnd('Confirmar recepción'));break;}
 case 'cancel-purchase':modal('Cancelar borrador de compra','Esta compra aún no generó movimientos de inventario.',formStart('cancelPurchase',`data-id="${id}"`)+`<p class="subtle">Se conservará el registro con estado Cancelada.</p>`+formEnd('Cancelar compra','danger'));break;
 case 'edit-product':editProduct(id);break;
 case 'product-detail':productDetail(id);break;
 case 'availability':perform('availability',{id},'Disponibilidad de la carta actualizada.');break;
 case 'soft-delete':{const r=state[d.entity].find(r=>r.id===+id);if(d.entity==='tables'){modal('Desactivar: '+h(r.name),'La mesa y su historial se conservan.',formStart('softDelete',`data-entity="${d.entity}" data-id="${id}"`)+note('La mesa dejará de estar disponible para nuevas atenciones. Podrás activarla nuevamente.')+formEnd('Desactivar mesa','danger'));break;}modal('Dar de baja: '+h(r.name),'Se conserva el registro y su historial. Podrás restaurarlo.',formStart('softDelete',`data-entity="${d.entity}" data-id="${id}"`)+textarea('Motivo de la baja lógica','reason','',true)+note('Se registrarán el usuario, la fecha y el motivo. Los pedidos, cobros y movimientos anteriores conservan sus datos.')+formEnd('Confirmar baja lógica','danger'));break;}
 case 'restore':perform('restore',{entity:d.entity,id},'Registro restaurado con su identidad e historial.');break;
 case 'record-meta':{const r=state[d.entity].find(r=>r.id===+id);modal('Trazabilidad · '+h(r.name),'Campos de auditoría y eliminación lógica del registro.',metaContent(r)+`<div class="modal-actions">${btn('Cerrar','close-modal')}</div>`);break;}
 case 'edit-contact':contactModal(id);break;
 case 'user-role':{const u=state.users.find(u=>u.id===+id);modal('Cambiar rol de '+h(u.name),'Configuración de ejemplo; no modifica una sesión real.',formStart('userRole',`data-id="${id}"`)+select('Rol del usuario','role',['Administradora','Mesero','Mesera','Cocinero','Cajero'].map(r=>option(r,r,u.role)).join(''))+formEnd('Guardar rol'));break;}
 case 'table-enabled':perform('tableEnabled',{id},'Disponibilidad de la mesa actualizada.');break;
 case 'invoice':invoiceModal();break;
 case 'receipt':receiptModal(id);break;
 case 'print':window.print();break;
 case 'export-audit':{const content=['Fecha,Usuario,Entidad,Registro,Acción,Detalle',...state.audit.map(a=>[a.at,a.actor,a.entity,a.record,a.action,a.detail].map(v=>'"'+String(v).replace(/^[=+\-@]/,"'$&").replaceAll('"','""')+'"').join(','))].join('\r\n');download('mesa-auditoria.csv','\ufeff'+content,'text/csv;charset=utf-8');toast('Historial descargado.');break;}
 case 'alerts':modal('Lo que necesita tu atención','Resumen de la operación actual.',`<div class="info-row"><span>Insumos por reponer</span><strong>${state.ingredients.filter(i=>stock(state,i.id)<i.min).length}</strong></div><div class="info-row"><span>Productos listos para servir</span><strong>${openOrders(state).flatMap(o=>o.lines).filter(l=>l.state==='LISTO').length}</strong></div><div class="info-row"><span>Pedidos con saldo pendiente</span><strong>${openOrders(state).filter(o=>balance(state,o)>0).length}</strong></div><div class="modal-actions">${btn('Ver cocina','go','data-page="cocina"','','chef')}${btn('Ver inventario','go','data-page="inventario"','primary','box')}</div>`);break;
 case 'reset':modal('Restablecer la demostración','Esta acción afecta únicamente los ejemplos de este navegador.',formStart('reset')+`<p class="subtle">Se borrarán los pedidos, pagos, cambios y eventos creados durante tus pruebas y se cargarán de nuevo los datos iniciales.</p>`+formEnd('Restablecer datos','danger'));break;
}}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',handleClick);
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-overlay'))closeModal();const sidebar=document.querySelector('#sidebar');if(sidebar?.classList.contains('open')&&!e.target.closest('#sidebar')&&!e.target.closest('[data-action="menu"]'))sidebar.classList.remove('open');});
document.addEventListener('submit',e=>{const form=e.target;if(!form.matches('form[data-form]'))return;e.preventDefault();const action=form.dataset.form;const fd=new FormData(form),data=Object.fromEntries(fd);for(const k of ['id','order','entity','payment'])if(form.dataset[k])data[k]=form.dataset[k];if(action==='reset'){state=seed();save();selected=1042;account=0;zone='Salón principal';closeModal();navigate('salon');toast('Datos de ejemplo restablecidos.');return;}if(action==='addLine')data.product=pickedProduct;if(action==='split')data.lines=fd.getAll('lines');if(action==='pay'){data.amount=toCents(data.amount);data.received=toCents(data.received);}if(['refund','cashMovement'].includes(action))data.amount=toCents(data.amount);if(action==='closeCash')data.counted=toCents(data.counted);if(action==='openCash')data.opening=toCents(data.opening);if(action==='saveProduct')data.price=toCents(data.price);if(action==='purchase')data.lines=[...form.querySelectorAll('.purchase-row')].map(r=>({item:+r.querySelector('[name="item"]').value,qty:+r.querySelector('[name="qty"]').value,cost:toCents(r.querySelector('[name="cost"]').value)}));const messages={newOrder:'Pedido creado. Agrega los productos.',pay:'Cobro registrado correctamente.',receivePurchase:'Mercadería recibida; inventario actualizado.',softDelete:'Baja lógica registrada con usuario, fecha y motivo.',invoice:'Documento de demostración creado.',settings:'Datos del restaurante guardados.',reservation:'Reserva confirmada.',movement:'Movimiento registrado en el kardex.'};const result=perform(action,data,messages[action]||'Operación registrada correctamente.');if(result&&action==='newOrder'){selected=result.result;account=0;const o=orderById(selected);zone=o.table?state.tables.find(t=>t.id===o.table).zone:'Para llevar';navigate('salon');addProduct(selected);}if(result&&action==='split'){account=Math.max(...orderById(data.order).accounts);render();}if(result&&action==='invoice')receiptModal(state.invoices.at(-1).id);});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='order-account'){account=+el.value;render();}const form=el.closest('form');if(form?.dataset.form==='newOrder'&&el.name==='type')refreshOrderFields(el.value);if(form?.dataset.form==='pay'){if(el.name==='account'){const due=balance(state,orderById(form.dataset.order),+el.value);form.elements.amount.value=(due/100).toFixed(2);form.elements.received.value=(due/100).toFixed(2);document.querySelector('#payment-balance').textContent=money(due);}refreshPayment();}if(form?.dataset.form==='purchase'&&el.name==='item'){const ingredient=state.ingredients.find(i=>i.id===+el.value);el.closest('.purchase-row').querySelector('[name="cost"]').value=(ingredient.cost/100).toFixed(2);}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='page-search'){const pos=el.selectionStart;query=el.value;render();const n=document.querySelector('#page-search');n.focus();if(n.type!=='search')n.setSelectionRange(pos,pos);}if(el.id==='product-search')document.querySelector('#product-picker').innerHTML=productPicker(el.value);if(el.closest('form')?.dataset.form==='pay')refreshPayment();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.querySelector('#sidebar')?.classList.remove('open');}if(e.key==='Tab'&&modalRoot.firstElementChild){const items=[...modalRoot.querySelectorAll('button:not([disabled]),input:not([type="hidden"]),select,textarea,a[href]')].filter(el=>!el.closest('[hidden]')&&el.getClientRects().length);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'salon';query='';showInactive=false;account=0;closeModal();render();});
render();
